/// <summary>
/// designed from ava
/// </summary>
[ExtensionOf(formControlStr(SalesQuotationTable, AVAQuotationViaMail))]
internal final class AVASalesQuotationTableFrm_AVAQuotationViaMail_Extension
{

}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
public void clicked()
{
    FormControl curButton = any2Object(this) as FormControl;
    FormDataSource          quotationDS = curButton.formRun().dataSource(tableStr(SalesQuotationTable));
    SalesQuotationTable     salesQuotationTable;
    if (quotationDS)
    {
        salesQuotationTable.data(quotationDS.cursor());
    }
    if (salesQuotationTable.Email == '')
    {
        throw Error("@NDX:NXANoRecipientEmail");
    }

    next clicked();

    Args args = new Args();
    args.record(salesQuotationTable);
    args.caller(curButton);

    new MenuFunction(menuItemActionStr(AVACreateQuotationJournal), MenuItemType::Action).run(args);

    CustQuotationJour           lastCustQuotationJour = CustQuotationJour::avaFindLatestQuotation(salesQuotationTable.QuotationId);
    args = new Args();
    args.record(lastCustQuotationJour);
    args.caller(curButton);

    new MenuFunction(menuItemActionStr(AVAERQuotationEmailCreation), MenuItemType::Action).run(args);

    if (quotationDS)
    {
        quotationDS.executeQuery();
        quotationDS.positionToRecord(salesQuotationTable);
    }
}
